OUT=ROOT/'iteration129'
BUDGETS=[0,5,20,50,100,179]

def mask_budget(public,targets,allowed):
    return [dict(s,tokens=[dict(t,anchor=None,tag='X') if t['id'] in targets or t['anchor'] not in allowed else dict(t) for t in s['tokens']]) for s in public]

