    save(OUT/'design-freeze.json',dict(inputs={str(p):digest(p) for p in paths},design='SOURCE-TEST development anchordependence challenge, NOTnewconfirmation. Exact118770/9956, all16targetnames/classes hidden everybudget; remaining179suppliedanchors ranked by49FITwordfrequency desc/lexicalties. Fixedbudgets0,5,20,50,100,179, no testpickedbudget. RemoveotheranchoridentityANDtag, opaqueID unchanged and stillgroupsoccurrences. Frozen124classmodel/13OOFoffset recomputeALL16profiles eachbudget (supportreportonly), threshold.5; no training/recalibration. Frozen12732Soboltypeconsistentdraws seed12700, original85PPmodel. Frozen128posteriorPPcut.4849530056062174 globally unchanged acrossbudgets. Compareunknown/hard/posterior at SAMEcut primary; oldcut.8 secondary, bothallsettingsreported no bestcut. Fixed120cohorts all/originalunmapped/targets/othergivenanchors evenwhenanchorsremoved. Referenceclasses attachedONLYafterclasspredictionfreeze; cached85PPlabelsonly. Freezeallbudgetviews/probabilities BEFOREPPscores, freezePPscores BEFOREmetrics. Full179 MUSTreproduce124classpreds/127PPscores. Primaryrelevance: classaccuracy/NLL vsprior andmatchingunknownPPmetrics acrossALLbudgets; quotequality/coverage/suppliedanchortokenfraction. No automatic90%claims/testtuning/newannotations/author/reserve/sealedlexicaltest/defaultchange/nuclei. 0budgetstillhascataloguemembership/segmentation/targetgrouping/trainedmodels=>notblindVoynich. Frozenfullcontextmodels may distribution-shift whenanchorsremoved; do notinfer absenceofallpossible lowanchor methods.'))
    anchors=load(ROOT/'iteration85/anchor-budgets.json')['195'];words=load(ROOT/'iteration93/types.json')['candidates'];part=load(ROOT/'iteration49/manifest.json')['partitions']['0'];reserved={r['sent_id'] for rr in load('experiments/holdouts/grammar-construction-next.json')['authors'].values() for r in rr};assert not set(part['fit']+part['test'])&reserved;cache=load(ROOT/'iteration44/annotations-truth.json');counts=Counter(t['word'] for sid in part['fit'] for t in cache[sid]['tokens']);ranked=sorted(set(anchors)-set(words),key=lambda w:(-counts[w],w));assert len(ranked)==179;save(OUT/'anchor-ranking.json',[dict(type=w,fit_count=counts[w],given_class=anchors[w]) for w in ranked]);public=load(ROOT/'iteration118/public.json');assert [s['sent_id'] for s in public]==part['test'];oldrows=load(ROOT/'iteration124/predictions.json');lookup={r['type']:r['opaque'] for r in oldrows};targets=set(lookup.values());model=load(ROOT/'iteration124/models.json')['final'];cal=load(ROOT/'iteration124/calibrator.json');predictions={};views={};probs={};selection={}
    for n in BUDGETS:
        key=str(n);view=mask_budget(public,targets,set(ranked[:n]));views[key]=view;profiles=grouped_profile(view,words,lookup,targets,model);predictions[key]=[dict(type=w,opaque=lookup[w],n=p['n'],sentences=p['sentences'],supported=p['n']>=5 and p['sentences']>=3,probabilities=dict(balanced124=float(apply_offset([p['mean']],cal)[0]),raw=p['mean'],prior=.5)) for w,p in sorted(profiles.items())];probs[key]={r['opaque']:r['probabilities']['balanced124'] for r in predictions[key]};selection[key]=dict(allowed=ranked[:n],given_anchor_tokens=sum(t['anchor'] is not None for s in view for t in s['tokens']),total_tokens=sum(len(s['tokens']) for s in view));save(OUT/('public-'+key+'.json'),view)
    save(OUT/'selection.json',selection);save(OUT/'predictions.json',predictions);save(OUT/'probabilities.json',probs);save(OUT/'input-freeze.json',dict(inputs={str(p):digest(p) for p in [OUT/'anchor-ranking.json',OUT/'selection.json',OUT/'predictions.json',OUT/'probabilities.json']+list(OUT.glob('public-*.json'))}));labels=[dict(sid=r['sid'],index=r['index'],labels=r['labels']) for r in load(BASE/'predictions.json')];scores={}
